using System.Collections.Generic;
using NUnit.Framework;
using WFC.Core;
using WFC.Terrain;
// ReSharper disable HeapView.BoxingAllocation
// ReSharper disable HeapView.ObjectAllocation
// Tests generated by Claude


namespace WFC.Tests {
    /// <summary> EditMode tests for the Unity specific terrain. </summary>
    public class WFCTerrainTests {
        // ---------------------------------------------------------------- standard sheet layouts
        [Test]
        public void StandardLayoutsCoverAll47Tiles() {
            foreach (BlobLayout lay in new[] { BlobLayouts.GODOT12_X4, BlobLayouts.GAME_MAKER8_X6 }) {
                HashSet<int> seen   = new();
                int          filled = 0;
                foreach (int m in lay.cellMasks) {
                    if (m < 0) continue;
                    filled++;
                    seen.Add(m);
                    Assert.AreEqual(m, OverlayMasks.StandardCanonical(m), lay.name);
                }

                Assert.AreEqual(47, filled, lay.name);
                Assert.AreEqual(47, seen.Count, lay.name);
                HashSet<int> all = new();
                for (int m = 0; m < 256; m++) {
                    all.Add(OverlayMasks.StandardCanonical(m));
                }

                Assert.IsTrue(all.SetEquals(seen), lay.name + " does not cover the canonical masks");
                // SlotToCell is a bijection onto the filled cells
                HashSet<int> cells = new(lay.slotToCell);
                Assert.AreEqual(47, cells.Count);
                foreach (int c in cells) Assert.IsTrue(lay.cellMasks[c] >= 0);
            }

            Assert.AreEqual(-1, BlobLayouts.GODOT12_X4.cellMasks[1 * 12 + 10]); // the one empty cell
            Assert.AreEqual(-1, BlobLayouts.GAME_MAKER8_X6.cellMasks[0]);        // GameMaker's reserved tile 0
        }

        [Test]
        public void OverlayMaskPicksTheTileWithEdgeArtOnThoseSides() {
            foreach (BlobLayout lay in new[] { BlobLayouts.GODOT12_X4, BlobLayouts.GAME_MAKER8_X6 }) {
                for (int raw = 0; raw < 256; raw++) {
                    int cell = lay.slotToCell[OverlayMasks.BlobIndex(raw)];
                    Assert.AreEqual(OverlayMasks.ToStandardMask(raw), lay.cellMasks[cell], $"{lay.name} raw {raw}");
                }
            }

            // overlay terrain only to the north: edge art on the north side = the tile whose other seven neighbours are the same terrain
            int north = BlobLayouts.GODOT12_X4.cellMasks[
                BlobLayouts.GODOT12_X4.slotToCell[OverlayMasks.BlobIndex(OverlayMasks.N)]];
            Assert.AreEqual(OverlayMasks.E | OverlayMasks.SE | OverlayMasks.S | OverlayMasks.SW | OverlayMasks.W, north);
            // overlay on all four sides = the isolated tile (standard mask 0)
            Assert.AreEqual(0, BlobLayouts.GODOT12_X4.cellMasks[BlobLayouts.GODOT12_X4.slotToCell[OverlayMasks.BlobIndex(85)]]);
        }

        [Test]
        public void SpritePositionsOnASheetFindTheirSlots() {
            foreach (BlobLayout lay in new[] { BlobLayouts.GODOT12_X4, BlobLayouts.GAME_MAKER8_X6 }) {
                const int    CELL = 16;
                int          w    = lay.columns * CELL, h = lay.rows * CELL;
                HashSet<int> seen = new();
                for (int row = 0; row < lay.rows; row++) {
                    for (int col = 0; col < lay.columns; col++) {
                        int idx = row * lay.columns + col;
                        if (lay.cellMasks[idx] < 0) continue;
                        float cx    = col * CELL + CELL / 2f, cyUp = (lay.rows - 1 - row) * CELL + CELL / 2f;
                        int   found = lay.CellAt(cx, cyUp, w, h);
                        Assert.AreEqual(idx, found, lay.name);
                        int slot = lay.cellToSlot[found];
                        Assert.IsTrue(slot >= 0);
                        seen.Add(slot);
                        Assert.AreEqual(idx, lay.slotToCell[slot]);

                        // sliced without its empty cell
                        // Unity rect: x from the left, y from the BOTTOM of the texture
                    }
                }

                Assert.AreEqual(47, seen.Count, lay.name);
                Assert.AreEqual(-1, lay.CellAt(-1f, 5f, w, h));
                Assert.AreEqual(-1, lay.CellAt(5f, h + 1f, w, h));
            }
        }
    }
}